body.script:
//
    // Single Page Application Client State
    const state = {
        view: 'INITIALIZING', // 'LOGIN' | 'SIGNUP' | 'EMPLOYEE_DASHBOARD' | 'HR_ADMIN_DASHBOARD'
        user: null,
        loading: false,
        error: null,
        successMsg: null
    };

    // Helper to execute JSON-RPC API requests to Dayflow Odoo backend
    async function callApi(endpoint, params = {}) {
        try {
            const response = await fetch(endpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json'
                },
                credentials: 'include',
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    id: Date.now(),
                    params: params
                })
            });

            if (!response.ok) {
                throw new Error(`Server returned HTTP ${response.status}`);
            }

            const data = await response.json();
            if (data.error) {
                const msg = data.error.data?.message || data.error.message || 'API operation failed.';
                throw new Error(msg);
            }
            return data.result;
        } catch (err) {
            console.error(`API Error [${endpoint}]:`, err);
            throw err;
        }
    }

    // Application Startup Initialization
    async function initApp() {
        try {
            const result = await callApi('/dayflow/auth/me');
            if (result && result.status === 'authenticated' && result.uid) {
                state.user = result;
                state.view = result.role === 'hr_admin' ? 'HR_ADMIN_DASHBOARD' : 'EMPLOYEE_DASHBOARD';
            } else {
                state.view = 'LOGIN';
            }
        } catch (err) {
            // Session expired or unauthenticated
            state.view = 'LOGIN';
        } finally {
            render();
        }
    }

    // Action: Login Submit
    async function handleLogin(e) {
        e.preventDefault();
        state.error = null;
        state.loading = true;
        render();

        const email = document.getElementById('login-email').value.trim();
        const password = document.getElementById('login-password').value.trim();

        if (!email || !password) {
            state.error = 'Please enter both email and password.';
            state.loading = false;
            render();
            return;
        }

        try {
            const result = await callApi('/dayflow/auth/login', { login: email, password: password });
            if (result && result.status === 'success') {
                state.user = result;
                state.view = result.role === 'hr_admin' ? 'HR_ADMIN_DASHBOARD' : 'EMPLOYEE_DASHBOARD';
                state.error = null;
            } else {
                state.error = result.message || 'Invalid login credentials.';
            }
        } catch (err) {
            state.error = err.message || 'Failed to log in. Please check credentials.';
        } finally {
            state.loading = false;
            render();
        }
    }

    // Action: Signup Submit
    async function handleSignup(e) {
        e.preventDefault();
        state.error = null;
        state.successMsg = null;
        state.loading = true;
        render();

        const empId = document.getElementById('signup-empid').value.trim();
        const name = document.getElementById('signup-name').value.trim();
        const email = document.getElementById('signup-email').value.trim();
        const password = document.getElementById('signup-password').value.trim();
        const role = document.getElementById('signup-role').value;

        if (!empId || !name || !email || !password) {
            state.error = 'All fields are required.';
            state.loading = false;
            render();
            return;
        }

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) {
            state.error = 'Please enter a valid email address.';
            state.loading = false;
            render();
            return;
        }

        try {
            const result = await callApi('/dayflow/auth/register', {
                employee_id: empId,
                name: name,
                email: email,
                password: password,
                role: role
            });

            if (result && result.status === 'success') {
                state.successMsg = 'Account registered successfully! Logging you in...';
                render();

                // Auto Login after successful signup
                const loginRes = await callApi('/dayflow/auth/login', { login: email, password: password });
                if (loginRes && loginRes.status === 'success') {
                    state.user = loginRes;
                    state.view = loginRes.role === 'hr_admin' ? 'HR_ADMIN_DASHBOARD' : 'EMPLOYEE_DASHBOARD';
                    state.successMsg = null;
                } else {
                    state.view = 'LOGIN';
                    state.successMsg = 'Account created. Please log in.';
                }
            } else {
                state.error = result.message || 'Registration failed.';
            }
        } catch (err) {
            state.error = err.message || 'Registration failed.';
        } finally {
            state.loading = false;
            render();
        }
    }

    // Action: Logout
    async function handleLogout() {
        state.loading = true;
        render();
        try {
            await callApi('/dayflow/auth/logout');
        } catch (err) {
            console.warn('Logout API call exception:', err);
        } finally {
            state.user = null;
            state.view = 'LOGIN';
            state.loading = false;
            state.error = null;
            state.successMsg = null;
            render();
        }
    }

    // Render UI Views based on current state
    function render() {
        const root = document.getElementById('app-root');
        if (!root) return;

        if (state.view === 'INITIALIZING') {
            root.innerHTML = `
                <div class="page-loader">
                    <div class="spinner" style="width: 36px; height: 36px; border-width: 3px;"></div>
                    <p style="font-weight: 500;">Initializing Dayflow HRMS...</p>
                </div>
            `;
            return;
        }

        let contentHtml = '';

        // Navbar for Authenticated Users
        const navbarHtml = state.user ? `
            <header class="navbar">
                <div class="brand-logo">
                    <div class="brand-icon">D</div>
                    Dayflow HRMS
                </div>
                <div class="user-nav-profile">
                    <span class="badge ${state.user.role === 'hr_admin' ? 'badge-admin' : 'badge-employee'}">
                        ${state.user.role === 'hr_admin' ? 'HR / Admin' : 'Employee'}
                    </span>
                    <div style="text-align: right;">
                        <div style="font-weight: 600; font-size: 0.95rem;">${escapeHtml(state.user.name || state.user.login)}</div>
                        <div style="font-size: 0.75rem; color: var(--text-muted);">ID: ${escapeHtml(state.user.employee_code || 'N/A')}</div>
                    </div>
                    <button class="btn-logout" onclick="handleLogout()">Logout</button>
                </div>
            </header>
        ` : '';

        if (state.view === 'LOGIN') {
            contentHtml = `
                <div class="auth-wrapper">
                    <div class="auth-card">
                        <div class="brand-logo" style="margin-bottom: 1.5rem;">
                            <div class="brand-icon">D</div>
                            Dayflow
                        </div>
                        <h1 class="auth-title">Welcome Back</h1>
                        <p class="auth-subtitle">Log in to manage your HRMS profile and portal</p>

                        ${state.error ? `<div class="alert alert-error">⚠️ ${escapeHtml(state.error)}</div>` : ''}
                        ${state.successMsg ? `<div class="alert alert-success">✓ ${escapeHtml(state.successMsg)}</div>` : ''}

                        <form onsubmit="handleLogin(event)">
                            <div class="form-group">
                                <label class="form-label" for="login-email">Email Address</label>
                                <input type="email" id="login-email" class="form-input" placeholder="name@company.com" required="required" autocomplete="email" />
                            </div>
                            <div class="form-group">
                                <label class="form-label" for="login-password">Password</label>
                                <input type="password" id="login-password" class="form-input" placeholder="••••••••" required="required" autocomplete="current-password" />
                            </div>
                            <button type="submit" class="btn-primary" ${state.loading ? 'disabled' : ''}>
                                ${state.loading ? '<div class="spinner"></div> Authenticating...' : 'Sign In'}
                            </button>
                        </form>

                        <div class="auth-footer">
                            Don't have an account? 
                            <span class="auth-link" onclick="state.view='SIGNUP'; state.error=null; render();">Create Account</span>
                        </div>
                    </div>
                </div>
            `;
        } else if (state.view === 'SIGNUP') {
            contentHtml = `
                <div class="auth-wrapper">
                    <div class="auth-card">
                        <div class="brand-logo" style="margin-bottom: 1.5rem;">
                            <div class="brand-icon">D</div>
                            Dayflow
                        </div>
                        <h1 class="auth-title">Create Account</h1>
                        <p class="auth-subtitle">Register your employee profile with Dayflow HRMS</p>

                        ${state.error ? `<div class="alert alert-error">⚠️ ${escapeHtml(state.error)}</div>` : ''}

                        <form onsubmit="handleSignup(event)">
                            <div class="form-group">
                                <label class="form-label" for="signup-empid">Employee ID</label>
                                <input type="text" id="signup-empid" class="form-input" placeholder="e.g. EMP101" required="required" />
                            </div>
                            <div class="form-group">
                                <label class="form-label" for="signup-name">Full Name</label>
                                <input type="text" id="signup-name" class="form-input" placeholder="John Doe" required="required" />
                            </div>
                            <div class="form-group">
                                <label class="form-label" for="signup-email">Work Email Address</label>
                                <input type="email" id="signup-email" class="form-input" placeholder="john@company.com" required="required" />
                            </div>
                            <div class="form-group">
                                <label class="form-label" for="signup-password">Password</label>
                                <input type="password" id="signup-password" class="form-input" placeholder="••••••••" required="required" minlength="6" />
                            </div>
                            <div class="form-group">
                                <label class="form-label" for="signup-role">Dayflow Role</label>
                                <select id="signup-role" class="form-select">
                                    <option value="Employee">Employee</option>
                                    <option value="HR/Admin">HR / Admin</option>
                                </select>
                            </div>
                            <button type="submit" class="btn-primary" ${state.loading ? 'disabled' : ''}>
                                ${state.loading ? '<div class="spinner"></div> Registering...' : 'Complete Registration'}
                            </button>
                        </form>

                        <div class="auth-footer">
                            Already registered? 
                            <span class="auth-link" onclick="state.view='LOGIN'; state.error=null; render();">Sign In</span>
                        </div>
                    </div>
                </div>
            `;
        } else if (state.view === 'EMPLOYEE_DASHBOARD') {
            contentHtml = `
                ${navbarHtml}
                <main class="dashboard-container">
                    <section class="welcome-hero">
                        <span class="badge badge-employee" style="margin-bottom: 0.75rem; display: inline-block;">Employee Portal</span>
                        <h1 style="font-size: 2rem; font-weight: 800; margin-bottom: 0.5rem;">Welcome back, ${escapeHtml(state.user.name || 'Employee')}! 👋</h1>
                        <p style="color: var(--text-muted); font-size: 1rem;">Employee ID: <strong style="color: var(--text-main);">${escapeHtml(state.user.employee_code || 'N/A')}</strong> | Email: <strong style="color: var(--text-main);">${escapeHtml(state.user.login)}</strong></p>
                    </section>

                    <div class="grid-3">
                        <div class="dash-card">
                            <div class="dash-card-title">⏱️ Attendance &amp; Check-in</div>
                            <div class="dash-card-desc">Log your daily work hours, check-in times, and break duration.</div>
                            <div style="margin-top: 1.25rem; font-size: 0.85rem; color: var(--accent-emerald); font-weight: 600;">Status: Active Session</div>
                        </div>
                        <div class="dash-card">
                            <div class="dash-card-title">📅 Leave Requests</div>
                            <div class="dash-card-desc">Apply for annual leave, sick leave, and track your remaining balance.</div>
                            <div style="margin-top: 1.25rem; font-size: 0.85rem; color: #818cf8; font-weight: 600;">Balance: 14 Days Available</div>
                        </div>
                        <div class="dash-card">
                            <div class="dash-card-title">💳 My Payslips</div>
                            <div class="dash-card-desc">View monthly salary statements, tax deductions, and download PDF slips.</div>
                            <div style="margin-top: 1.25rem; font-size: 0.85rem; color: var(--accent-amber); font-weight: 600;">Latest: Ready for Download</div>
                        </div>
                    </div>
                </main>
            `;
        } else if (state.view === 'HR_ADMIN_DASHBOARD') {
            contentHtml = `
                ${navbarHtml}
                <main class="dashboard-container">
                    <section class="welcome-hero">
                        <span class="badge badge-admin" style="margin-bottom: 0.75rem; display: inline-block;">HR / Admin Portal</span>
                        <h1 style="font-size: 2rem; font-weight: 800; margin-bottom: 0.5rem;">HR Management Control Center</h1>
                        <p style="color: var(--text-muted); font-size: 1rem;">Administrator: <strong style="color: var(--text-main);">${escapeHtml(state.user.name || state.user.login)}</strong> | ID: <strong style="color: var(--text-main);">${escapeHtml(state.user.employee_code || 'N/A')}</strong></p>
                    </section>

                    <div class="grid-3">
                        <div class="dash-card">
                            <div class="dash-card-title">👥 Employee Directory</div>
                            <div class="stat-number">28</div>
                            <div class="dash-card-desc">Total registered employees across all departments.</div>
                        </div>
                        <div class="dash-card">
                            <div class="dash-card-title">📋 Pending Leave Approvals</div>
                            <div class="stat-number" style="background: linear-gradient(135deg, #f59e0b, #fbbf24); -webkit-background-clip: text; -webkit-text-fill-color: transparent;">3</div>
                            <div class="dash-card-desc">Leave applications awaiting administrative review.</div>
                        </div>
                        <div class="dash-card">
                            <div class="dash-card-title">💼 Payroll Processing</div>
                            <div class="stat-number" style="background: linear-gradient(135deg, #10b981, #34d399); -webkit-background-clip: text; -webkit-text-fill-color: transparent;">Active</div>
                            <div class="dash-card-desc">Monthly salary computations and payment dispatches.</div>
                        </div>
                    </div>
                </main>
            `;
        }

        root.innerHTML = contentHtml;
    }

    function escapeHtml(str) {
        if (!str) return '';
        return String(str)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }

    // Run init on DOM load
    document.addEventListener('DOMContentLoaded', initApp);
//
